// Tests for GifDecoderGpu (Images/Gif).
//
// Fixtures (TestData/Gif, generated by scripts/images/make_gif_fixtures.py) cover 2..256 colour palettes, odd
// sizes, 87a, interlacing at 14 heights, local / global palettes, gray-ramp palettes, transparency, LZW corners
// (the 4096-entry table filling and clearing, the deferred-clear stream shape, no leading clear / no end code,
// 1-byte sub-blocks), skipped extensions, loop counts, a missing trailer, animations with every disposal method,
// partial / clipped / interlaced frames, a 70-frame file that crosses the decoder's 64-frame batch, files written
// by Pillow's own encoder, 64 random animations, and hostile streams (bad_*) that must be rejected.
//
// Two truths per fixture, both whole-animation (frame k at k * W * H * 4):
//   <name>.pil.rgba8  what PILLOW 13 shows (Image.seek(k) + convert("RGBA")): the oracle for GifCompositing.Pillow,
//                     the decoder's default. It is Pillow's output, never ours.
//   <name>.web.rgba8  the canvas built from the index arrays the file was made FROM and the browser compositing
//                     rules: the oracle for GifCompositing.Web.
// A test that cannot fail is not a test: SomeFixturesDifferBetweenTheTwoTruths proves the two truths disagree on
// real frames, so a decoder that ignored the Compositing property would fail one of the two comparison tests.
//
// What can fail: the managed and ArrayView1D overloads (the latter into a caller buffer pre-filled with 0xAB and
// longer than needed, with garbage after fileLength), every frame of every animation (DecodeFrameAsync), RGBA16
// output, ReadInfo / ReadFrames / ReadLoopCount facts, and the error paths, which must throw ImageDecodeException
// with the specific reason.

using System.Text.Json;
using ILGPU;
using ILGPU.Runtime;
using SpawnDev.Codecs.Images;
using SpawnDev.Codecs.Images.Gif;
using SpawnDev.ILGPU;
using SpawnDev.UnitTesting;
using static SpawnDev.Codecs.Demo.Shared.UnitTests.TestHelpers;

namespace SpawnDev.Codecs.Demo.Shared.UnitTests;

public abstract partial class CodecsTestBase
{
    private const string GifFixturePrefix = "SpawnDev.Codecs.Demo.Shared.TestData.Gif.";

    private static byte[] GifFixture(string name) => ReadEmbedded(GifFixturePrefix + name + ".gif");

    /// <summary>Names of the valid fixtures (everything not starting with bad_).</summary>
    private static string[] GifValidFixtureNames() =>
        GifBmpFixtureNames(GifFixturePrefix, ".gif").Where(n => !n.StartsWith("bad_", StringComparison.Ordinal)).ToArray();

    private static string[] GifHostileFixtureNames() =>
        GifBmpFixtureNames(GifFixturePrefix, ".gif").Where(n => n.StartsWith("bad_", StringComparison.Ordinal)).ToArray();

    private static JsonElement GifMetaJson(string name)
    {
        using var doc = JsonDocument.Parse(ReadEmbedded(GifFixturePrefix + name + ".json"));
        return doc.RootElement.Clone();
    }

    private static int GifFrameCount(JsonElement meta) => meta.GetProperty("frames").GetArrayLength();

    /// <summary>All frames' expected canvases of the given truth kind ("pil" or "web"), or null when the fixture has none.</summary>
    private static byte[][]? GifTruth(string name, string kind, JsonElement meta)
    {
        string resource = GifFixturePrefix + name + "." + kind + ".rgba8";
        if (!HasEmbedded(resource)) return null;
        var all = ReadEmbedded(resource);
        int frames = GifFrameCount(meta);
        int size = meta.GetProperty("width").GetInt32() * meta.GetProperty("height").GetInt32() * 4;
        Equal(frames * size, all.Length, $"{name}.{kind}.rgba8 length");
        var result = new byte[frames][];
        for (int k = 0; k < frames; k++) result[k] = all.AsSpan(k * size, size).ToArray();
        return result;
    }

    /// <summary>Decodes frame k alternately through the managed and the ArrayView1D overload and compares with the truth.</summary>
    private static async Task<string?> GifCheckFrameAsync(
        GifDecoderGpu dec, Accelerator acc, string name, byte[] gif, ArrayView1D<byte, Stride1D.Dense> dFile, int k,
        byte[] expected, int width)
    {
        byte[] pixels;
        if (k % 2 == 0)
        {
            var img = await dec.DecodeFrameAsync(gif, k);
            pixels = img.Pixels;
        }
        else
        {
            using var dOut = acc.Allocate1D<byte>(expected.Length + 7);
            var fill = new byte[dOut.Length];
            System.Array.Fill(fill, (byte)0xAB);
            DeviceTransfer.Upload(dOut.View, fill);
            await dec.DecodeFrameAsync(dFile, gif.Length, k, dOut.View);
            pixels = await DeviceTransfer.DownloadAsync(dOut.View, expected.Length);
            var tail = await dOut.View.SubView(expected.Length, 7).CopyToHostAsync();
            if (tail.Any(b => b != 0xAB)) return $"{name} frame {k} [ArrayView1D]: wrote past the end of the canvas";
        }
        var diff = ComparePixels(expected, pixels, 4, width);
        return diff == null ? null : $"{name} frame {k}: {diff}";
    }

    private async Task GifEveryFrameMatchesAsync(GifCompositing mode, string kind, int minFrames)
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new GifDecoderGpu(acc) { Compositing = mode };
            var failures = new List<string>();
            int frameChecks = 0, fixtures = 0;
            foreach (var name in GifValidFixtureNames())
            {
                var meta = GifMetaJson(name);
                var truth = GifTruth(name, kind, meta);
                if (truth == null) continue;
                byte[] gif = GifFixture(name);
                try
                {
                    var info = await dec.ReadInfoAsync(gif);
                    if (info.FrameCount != truth.Length) { failures.Add($"{name}: ReadInfo.FrameCount {info.FrameCount} != {truth.Length}"); continue; }
                    using var dFile = acc.Allocate1D<byte>(gif.Length);
                    DeviceTransfer.Upload(dFile.View, gif);
                    string? firstFailure = null;
                    int failedFrames = 0;
                    for (int k = 0; k < truth.Length; k++)
                    {
                        var failure = await GifCheckFrameAsync(dec, acc, name, gif, dFile.View, k, truth[k], info.Width);
                        if (failure != null) { firstFailure ??= failure; failedFrames++; }
                        frameChecks++;
                    }
                    // One line per fixture: the first bad frame and how many frames of that fixture were bad.
                    if (firstFailure != null) failures.Add($"{firstFailure}  [{failedFrames} of {truth.Length} frames bad]");
                    fixtures++;
                }
                catch (Exception ex)
                {
                    failures.Add($"{name}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            True(frameChecks >= minFrames, $"only {frameChecks} frames of {fixtures} fixtures were exercised (wanted {minFrames})");
            True(failures.Count == 0,
                $"{mode}: {failures.Count} frame failures against the {kind} truth ({frameChecks} frames, {fixtures} fixtures checked):\n" +
                string.Join("\n", failures.Take(60)));
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    [TestMethod]
    public Task GifDecoderGpu_PillowCompositing_EveryFrameOfEveryFixture_MatchesPillow()
        => GifEveryFrameMatchesAsync(GifCompositing.Pillow, "pil", 450);

    [TestMethod]
    public Task GifDecoderGpu_WebCompositing_EveryFrameOfEveryFixture_MatchesSpecTruth()
        => GifEveryFrameMatchesAsync(GifCompositing.Web, "web", 430);

    [TestMethod]
    public void GifDecoderGpu_SomeFixturesDifferBetweenThePillowAndWebTruths()
    {
        CpuOnlyTest();
        // If the two modes agreed everywhere, the two tests above would not prove that Compositing does anything.
        var differing = new List<string>();
        foreach (var name in GifValidFixtureNames())
        {
            var meta = GifMetaJson(name);
            var pil = GifTruth(name, "pil", meta);
            var web = GifTruth(name, "web", meta);
            if (pil == null || web == null) continue;
            for (int k = 0; k < pil.Length; k++)
                if (!pil[k].AsSpan().SequenceEqual(web[k])) { differing.Add($"{name}#{k}"); break; }
        }
        True(differing.Count >= 8, $"expected the modes to disagree on at least 8 fixtures, found {differing.Count}: {string.Join(", ", differing)}");
        foreach (var must in new[] { "anim_dispose2", "anim_first_partial", "trans_index3", "anim_dispose_unspecified_and_reserved" })
            True(differing.Any(d => d.StartsWith(must + "#", StringComparison.Ordinal)), $"{must} must differ between the modes");
    }

    [TestMethod]
    public async Task GifDecoderGpu_DefaultMode_IsPillow_AndFirstFrameMatchesViaDecodeAsync()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new GifDecoderGpu(acc);
            Equal(GifCompositing.Pillow, dec.Compositing, "default Compositing");
            var failures = new List<string>();
            int checkedCount = 0;
            foreach (var name in GifValidFixtureNames())
            {
                var meta = GifMetaJson(name);
                var truth = GifTruth(name, "pil", meta);
                if (truth == null) continue;
                byte[] gif = GifFixture(name);
                try
                {
                    // Managed DecodeAsync.
                    var managed = await dec.DecodeAsync(gif);
                    var diff = ComparePixels(truth[0], managed.Pixels, 4, managed.Info.Width);
                    if (diff != null) failures.Add($"{name} [managed]: {diff}");

                    // ArrayView1D DecodeAsync: the file buffer is longer than the file and holds garbage after fileLength.
                    using var dFile = acc.Allocate1D<byte>(gif.Length + 33);
                    var padded = new byte[gif.Length + 33];
                    System.Array.Fill(padded, (byte)0xAB);
                    gif.CopyTo(padded, 0);
                    DeviceTransfer.Upload(dFile.View, padded);
                    using var dOut = acc.Allocate1D<byte>(truth[0].Length + 7);
                    var fill = new byte[dOut.Length];
                    System.Array.Fill(fill, (byte)0xAB);
                    DeviceTransfer.Upload(dOut.View, fill);
                    var info = await dec.DecodeAsync(dFile.View, gif.Length, dOut.View, PixelFormat.Rgba8);
                    var viewPixels = await DeviceTransfer.DownloadAsync(dOut.View, truth[0].Length);
                    diff = ComparePixels(truth[0], viewPixels, 4, info.Width);
                    if (diff != null) failures.Add($"{name} [ArrayView1D]: {diff}");
                    var tail = await dOut.View.SubView(truth[0].Length, 7).CopyToHostAsync();
                    if (tail.Any(b => b != 0xAB)) failures.Add($"{name} [ArrayView1D]: wrote past the end of the canvas");
                    checkedCount++;
                }
                catch (Exception ex)
                {
                    failures.Add($"{name}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            True(checkedCount > 100, $"only {checkedCount} fixtures checked");
            True(failures.Count == 0, $"{failures.Count} of {checkedCount + failures.Count} GIF fixtures failed:\n" + string.Join("\n", failures.Take(40)));
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    [TestMethod]
    public async Task GifDecoderGpu_Rgba16_WidensEverySample_BothModes()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            var failures = new List<string>();
            int checkedCount = 0;
            foreach (var (mode, kind) in new[] { (GifCompositing.Pillow, "pil"), (GifCompositing.Web, "web") })
            {
                using var dec = new GifDecoderGpu(acc) { Compositing = mode };
                foreach (var name in new[] { "pal256_23x21", "trans_index3", "interlaced_h9", "anim_dispose3", "anim_mixed", "fuzz_pal_003" })
                {
                    var meta = GifMetaJson(name);
                    var truth = GifTruth(name, kind, meta);
                    if (truth == null) continue;
                    int last = truth.Length - 1;
                    var expected = new byte[truth[last].Length * 2];
                    for (int i = 0; i < truth[last].Length; i++) { expected[i * 2] = truth[last][i]; expected[i * 2 + 1] = truth[last][i]; }
                    try
                    {
                        var img = await dec.DecodeFrameAsync(GifFixture(name), last, PixelFormat.Rgba16);
                        var diff = ComparePixels(expected, img.Pixels, 8, img.Info.Width);
                        if (diff != null) failures.Add($"{mode} {name}: {diff}");
                        checkedCount++;
                    }
                    catch (Exception ex)
                    {
                        failures.Add($"{mode} {name}: {ex.GetType().Name}: {ex.Message}");
                    }
                }
            }
            True(checkedCount >= 8, $"only {checkedCount} RGBA16 decodes ran");
            True(failures.Count == 0, $"{failures.Count} RGBA16 GIF failures of {checkedCount + failures.Count}:\n" + string.Join("\n", failures));
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    [TestMethod]
    public async Task GifDecoderGpu_ReadFrames_ReadInfo_And_LoopCount_ReportTheFileStructure()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new GifDecoderGpu(acc);
            var failures = new List<string>();
            int loops = 0;
            foreach (var name in GifValidFixtureNames())
            {
                var meta = GifMetaJson(name);
                var jf = meta.GetProperty("frames");
                bool exact = meta.GetProperty("exactFrames").GetBoolean();
                try
                {
                    byte[] gif = GifFixture(name);
                    var info = await dec.ReadInfoAsync(gif);
                    var frames = await dec.ReadFramesAsync(gif);
                    int loop = await dec.ReadLoopCountAsync(gif);
                    int expectedLoop = meta.GetProperty("loop").ValueKind == JsonValueKind.Number ? meta.GetProperty("loop").GetInt32() : -1;
                    if (loop != expectedLoop) failures.Add($"{name}: loop count {loop} != {expectedLoop}");
                    loops++;
                    if (info.Format != ImageFormat.Gif) failures.Add($"{name}: format {info.Format}");
                    if (info.Width != meta.GetProperty("width").GetInt32() || info.Height != meta.GetProperty("height").GetInt32())
                        failures.Add($"{name}: canvas {info.Width}x{info.Height}");
                    if (info.FrameCount != jf.GetArrayLength() || frames.Length != jf.GetArrayLength())
                        failures.Add($"{name}: frame count info={info.FrameCount} frames={frames.Length} expected {jf.GetArrayLength()}");
                    if (info.BitDepth != 8 || info.Orientation != 1) failures.Add($"{name}: bit depth / orientation");
                    if (exact)
                    {
                        // HasAlpha: Pillow mode = some frame has a transparent index; Web mode also counts disposal 2 and a partial first frame.
                        if (info.HasAlpha != meta.GetProperty("hasTransparentIndex").GetBoolean())
                            failures.Add($"{name}: Pillow-mode HasAlpha {info.HasAlpha}");
                        dec.Compositing = GifCompositing.Web;
                        var webInfo = await dec.ReadInfoAsync(gif);
                        dec.Compositing = GifCompositing.Pillow;
                        if (webInfo.HasAlpha != meta.GetProperty("hasAlphaWeb").GetBoolean())
                            failures.Add($"{name}: Web-mode HasAlpha {webInfo.HasAlpha}");
                        bool anyInterlaced = false;
                        foreach (var f in jf.EnumerateArray()) anyInterlaced |= f.GetProperty("interlaced").GetBoolean();
                        if (info.IsInterlaced != anyInterlaced) failures.Add($"{name}: IsInterlaced {info.IsInterlaced}");
                    }
                    for (int k = 0; k < Math.Min(frames.Length, jf.GetArrayLength()); k++)
                    {
                        var e = jf[k];
                        var f = frames[k];
                        if (f.Index != k) failures.Add($"{name}[{k}]: Index {f.Index}");
                        if (f.DurationMs != e.GetProperty("delayMs").GetInt32())
                            failures.Add($"{name}[{k}]: DurationMs {f.DurationMs} != {e.GetProperty("delayMs").GetInt32()}");
                        if (!exact) continue;
                        if (f.X != e.GetProperty("x").GetInt32() || f.Y != e.GetProperty("y").GetInt32()
                            || f.Width != e.GetProperty("w").GetInt32() || f.Height != e.GetProperty("h").GetInt32())
                            failures.Add($"{name}[{k}]: rect {f.X},{f.Y} {f.Width}x{f.Height}");
                        if (f.Dispose.ToString() != e.GetProperty("dispose").GetString())
                            failures.Add($"{name}[{k}]: Dispose {f.Dispose} != {e.GetProperty("dispose").GetString()}");
                        if (f.Blend.ToString() != e.GetProperty("blend").GetString())
                            failures.Add($"{name}[{k}]: Blend {f.Blend} != {e.GetProperty("blend").GetString()}");
                    }
                }
                catch (Exception ex)
                {
                    failures.Add($"{name}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            True(loops > 100, $"only {loops} fixtures checked");
            True(failures.Count == 0, $"{failures.Count} structure failures:\n" + string.Join("\n", failures.Take(40)));
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    [TestMethod]
    public async Task GifDecoderGpu_LoopExtension_OnlyBeforeTheFirstImageCounts()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new GifDecoderGpu(acc);
            Equal(0, await dec.ReadLoopCountAsync(GifFixture("loop0")), "NETSCAPE loop 0 = forever");
            Equal(3, await dec.ReadLoopCountAsync(GifFixture("loop3")), "NETSCAPE loop 3");
            Equal(65535, await dec.ReadLoopCountAsync(GifFixture("loop65535")), "NETSCAPE loop 65535");
            Equal(-1, await dec.ReadLoopCountAsync(GifFixture("loop_none")), "no extension");
            Equal(-1, await dec.ReadLoopCountAsync(GifFixture("loop_after_first_frame")), "extension after the first image is ignored (Pillow)");
            Equal(0, await dec.ReadLoopCountAsync(GifFixture("extensions_skipped")), "loop extension next to comment / application extensions");
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    // ------------------------------------------------------------------
    // Error paths
    // ------------------------------------------------------------------

    private async Task AssertGifRejectedAsync(byte[] file, string expectedMessagePart, string what, int frame = 0)
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new GifDecoderGpu(acc);
            ImageDecodeException? caught = null;
            try { await dec.DecodeFrameAsync(file, frame); }
            catch (ImageDecodeException ex) { caught = ex; }
            NotNull(caught, $"{what}: expected ImageDecodeException");
            Contains(expectedMessagePart, caught!.Message, what);
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    [TestMethod]
    public async Task GifDecoderGpu_HostileFixtures_AreRejectedWithTheSpecificReason()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new GifDecoderGpu(acc);
            var failures = new List<string>();
            int count = 0;
            foreach (var name in GifHostileFixtureNames())
            {
                var meta = GifMetaJson(name);
                string reject = meta.GetProperty("reject").GetString()!;
                int frame = meta.GetProperty("frame").GetInt32();
                byte[] gif = GifFixture(name);
                foreach (var ok in meta.GetProperty("okFrames").EnumerateArray())
                {
                    try { await dec.DecodeFrameAsync(gif, ok.GetInt32()); }
                    catch (Exception ex) { failures.Add($"{name}: frame {ok.GetInt32()} must decode but threw {ex.GetType().Name}: {ex.Message}"); }
                }
                foreach (var compositing in new[] { GifCompositing.Pillow, GifCompositing.Web })
                {
                    dec.Compositing = compositing;
                    try
                    {
                        await dec.DecodeFrameAsync(gif, frame);
                        failures.Add($"{name}: decoded without an error, expected '{reject}'");
                    }
                    catch (ImageDecodeException ex)
                    {
                        if (!ex.Message.Contains(reject, StringComparison.Ordinal))
                            failures.Add($"{name}: message '{ex.Message}' does not contain '{reject}'");
                    }
                    catch (Exception ex)
                    {
                        failures.Add($"{name}: threw {ex.GetType().Name} instead of ImageDecodeException: {ex.Message}");
                    }
                }
                count++;
            }
            True(count >= 30, $"only {count} hostile fixtures");
            True(failures.Count == 0, $"{failures.Count} hostile-stream failures:\n" + string.Join("\n", failures));
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    /// <summary>
    /// A 2x2 GIF with a 4 entry global palette and one frame whose LZW data (min code size 2) is the given bytes
    /// (one sub-block). Codes are 3 bits, LSB first: clear = 4, end = 5, literals 0..3, first free code 6.
    /// </summary>
    private static byte[] TinyGif(byte[] lzw, int minCodeSize = 2, int w = 2, int h = 2, bool globalPalette = true)
    {
        var f = new List<byte>();
        f.AddRange(System.Text.Encoding.ASCII.GetBytes("GIF89a"));
        f.AddRange(new byte[] { (byte)w, 0, (byte)h, 0, (byte)(globalPalette ? 0x81 : 0x00), 0, 0 });
        if (globalPalette) f.AddRange(new byte[] { 0, 0, 0, 255, 0, 0, 0, 255, 0, 0, 0, 255 });
        f.AddRange(new byte[] { 0x2C, 0, 0, 0, 0, (byte)w, 0, (byte)h, 0, 0 });
        f.Add((byte)minCodeSize);
        f.Add((byte)lzw.Length);
        f.AddRange(lzw);
        f.Add(0);
        f.Add(0x3B);
        return f.ToArray();
    }

    /// <summary>Packs (code, width) pairs LSB first, like the LZW bit stream.</summary>
    private static byte[] LzwBits(params (int Code, int Width)[] codes)
    {
        var bytes = new List<byte>();
        long acc = 0;
        int n = 0;
        foreach (var (code, width) in codes)
        {
            acc |= (long)code << n;
            n += width;
            while (n >= 8) { bytes.Add((byte)acc); acc >>= 8; n -= 8; }
        }
        if (n > 0) bytes.Add((byte)acc);
        return bytes.ToArray();
    }

    [TestMethod]
    public async Task GifDecoderGpu_HandWrittenLzw_DecodesIncludingTheKwKwKCaseAndWidthChange()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new GifDecoderGpu(acc);
            // palette: 0 black, 1 red, 2 green, 3 blue
            // clear, 0, 1, 2 (adds entries 6 and 7; the width becomes 4 after entry 7), 3 at 4 bits, end at 4 bits.
            var img = await dec.DecodeAsync(TinyGif(LzwBits((4, 3), (0, 3), (1, 3), (2, 3), (3, 4), (5, 4))));
            EqualBytes(new byte[] { 0, 0, 0, 255, 255, 0, 0, 255, 0, 255, 0, 255, 0, 0, 255, 255 }, img.Pixels, "2x2 pixels");

            // KwKwK: clear, 1, then code 6 = next free entry ("1" + first char of "1") -> pixels 1, 1, 1; then 2.
            var k = await dec.DecodeAsync(TinyGif(LzwBits((4, 3), (1, 3), (6, 3), (2, 3), (5, 3)), w: 4, h: 1));
            EqualBytes(new byte[] { 255, 0, 0, 255, 255, 0, 0, 255, 255, 0, 0, 255, 0, 255, 0, 255 }, k.Pixels, "KwKwK 4x1 pixels");
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    /// <summary>
    /// Bulk comparison with Pillow on thousands of random animations that are too many to embed: generate them with
    /// <c>python -I scripts/images/make_gif_fixtures.py --fuzz-dir DIR COUNT SEED0</c> and point SPAWNDEV_GIF_FUZZ_DIR at DIR.
    /// Skipped (reported as Unsupported, never as passed) when the variable is not set.
    /// </summary>
    [TestMethod]
    public async Task GifDecoderGpu_FuzzDirectory_MatchesPillow()
    {
        string? dir = Environment.GetEnvironmentVariable("SPAWNDEV_GIF_FUZZ_DIR");
        if (OperatingSystem.IsBrowser() || string.IsNullOrEmpty(dir) || !Directory.Exists(dir))
            throw new UnsupportedTestException("Set SPAWNDEV_GIF_FUZZ_DIR to a folder made by make_gif_fixtures.py --fuzz-dir to run the bulk Pillow comparison.");
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new GifDecoderGpu(acc);
            var failures = new List<string>();
            int files = 0, frames = 0;
            foreach (var gifPath in Directory.EnumerateFiles(dir, "*.gif").OrderBy(p => p, StringComparer.Ordinal))
            {
                string stem = gifPath.Substring(0, gifPath.Length - 4);
                using var meta = JsonDocument.Parse(File.ReadAllBytes(stem + ".json"));
                int w = meta.RootElement.GetProperty("width").GetInt32(), h = meta.RootElement.GetProperty("height").GetInt32();
                int n = meta.RootElement.GetProperty("frames").GetInt32();
                byte[] gif = File.ReadAllBytes(gifPath);
                byte[] truth = File.ReadAllBytes(stem + ".pil.rgba8");
                int size = w * h * 4;
                try
                {
                    // Sequential playback, like Image.seek(0), seek(1), ...: every frame, managed overload.
                    for (int k = 0; k < n; k++)
                    {
                        var img = await dec.DecodeFrameAsync(gif, k);
                        var diff = ComparePixels(truth.AsSpan(k * size, size).ToArray(), img.Pixels, 4, w);
                        if (diff != null) { failures.Add($"{Path.GetFileName(gifPath)} frame {k}/{n}: {diff}"); break; }
                        frames++;
                    }
                    files++;
                }
                catch (Exception ex)
                {
                    failures.Add($"{Path.GetFileName(gifPath)}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            Console.WriteLine($"GifDecoderGpu_FuzzDirectory_MatchesPillow: {files} files, {frames} frames compared, {failures.Count} failures");
            True(files > 0, "no fuzz files found in " + dir);
            True(failures.Count == 0, $"{failures.Count} of {files} random animations differ from Pillow:\n" + string.Join("\n", failures.Take(40)));
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    [TestMethod]
    public async Task GifDecoderGpu_BadSignature_And_TinyInputs_AreRejected()
    {
        var gif = GifFixture("pal16_19x7");
        gif[1] = (byte)'X';
        await AssertGifRejectedAsync(gif, "bad signature", "bad signature");
        await AssertGifRejectedAsync(new byte[] { 1, 2, 3 }, "bad signature", "3 bytes");
        await AssertGifRejectedAsync(new byte[] { (byte)'G', (byte)'I', (byte)'F', (byte)'8', (byte)'9', (byte)'a', 1, 0, 1 }, "truncated", "9 bytes");
    }

    [TestMethod]
    public async Task GifDecoderGpu_TooManyFrames_IsRejected()
    {
        // 16385 one-pixel frames: the 16385th one is one more than a file may hold.
        var f = new List<byte>();
        f.AddRange(System.Text.Encoding.ASCII.GetBytes("GIF89a"));
        f.AddRange(new byte[] { 1, 0, 1, 0, 0x81, 0, 0 });
        f.AddRange(new byte[] { 0, 0, 0, 255, 0, 0, 0, 255, 0, 0, 0, 255 });
        var frame = new List<byte> { 0x2C, 0, 0, 0, 0, 1, 0, 1, 0, 0, 2, 2 };
        frame.AddRange(LzwBits((4, 3), (1, 3), (5, 3)));        // 9 bits = 2 bytes
        frame.Add(0);
        for (int i = 0; i < GifMeta.MaxFrames + 1; i++) f.AddRange(frame);
        f.Add(0x3B);
        await AssertGifRejectedAsync(f.ToArray(), $"more than {GifMeta.MaxFrames} frames", "16385 frames");
        // Exactly the limit is fine and every frame is addressable.
        var ok = f.Take(f.Count - 1 - frame.Count).Concat(new byte[] { 0x3B }).ToArray();
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new GifDecoderGpu(acc);
            var info = await dec.ReadInfoAsync(ok);
            Equal(GifMeta.MaxFrames, info.FrameCount, "FrameCount at the limit");
            var last = await dec.DecodeFrameAsync(ok, GifMeta.MaxFrames - 1);
            EqualBytes(new byte[] { 255, 0, 0, 255 }, last.Pixels, "last of 16384 frames");
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    [TestMethod]
    public async Task GifDecoderGpu_FrameIndexOutOfRange_Throws()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new GifDecoderGpu(acc);
            var gif = GifFixture("anim_dispose2");
            int caught = 0;
            try { await dec.DecodeFrameAsync(gif, 5); } catch (ArgumentOutOfRangeException) { caught++; }
            try { await dec.DecodeFrameAsync(gif, -1); } catch (ArgumentOutOfRangeException) { caught++; }
            Equal(2, caught, "frame 5 of 5 and frame -1 must throw ArgumentOutOfRangeException");
            var last = await dec.DecodeFrameAsync(gif, 4);
            Equal(5, last.Info.FrameCount, "FrameCount");
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    [TestMethod]
    public async Task GifDecoderGpu_OutputViewTooSmall_Throws_AndFileLengthIsValidated()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new GifDecoderGpu(acc);
            var gif = GifFixture("pal16_19x7");
            using var dFile = acc.Allocate1D<byte>(gif.Length);
            DeviceTransfer.Upload(dFile.View, gif);
            using var small = acc.Allocate1D<byte>(19 * 7 * 4 - 1);
            int caught = 0;
            try { await dec.DecodeAsync(dFile.View, gif.Length, small.View); } catch (ArgumentException) { caught++; }
            try { await dec.ReadInfoAsync(dFile.View, gif.Length + 1); } catch (ArgumentOutOfRangeException) { caught++; }
            try { await dec.ReadInfoAsync(dFile.View, 0); } catch (ArgumentOutOfRangeException) { caught++; }
            Equal(3, caught, "too-small output, fileLength beyond the view, fileLength 0");
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    [TestMethod]
    public async Task GifDecoderGpu_InstanceIsReusable_AcrossFilesSizesAndModes()
    {
        // One decoder instance decodes a big file, a tiny one, then the big one again (grow-only buffers must not leak state).
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new GifDecoderGpu(acc);
            var failures = new List<string>();
            foreach (var name in new[] { "noise4_deferred", "size_1x1", "anim_70_frames", "pal2_13x9", "noise4_deferred", "anim_dispose3", "anim_dispose3" })
            {
                var meta = GifMetaJson(name);
                var truth = GifTruth(name, "pil", meta)!;
                int last = truth.Length - 1;
                var img = await dec.DecodeFrameAsync(GifFixture(name), last);
                var diff = ComparePixels(truth[last], img.Pixels, 4, img.Info.Width);
                if (diff != null) failures.Add($"{name}: {diff}");
            }
            True(failures.Count == 0, string.Join("\n", failures));
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }
}
